18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String base = OwnerCustomerCodes.forOwner(owner);
21	        Set<String> taken = new HashSet<>();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (existing.getCustomerCode() != null) {
24	                taken.add(existing.getCustomerCode());
25	            }
26	        }
27	        owner.setCustomerCode(OwnerCustomerCodes.deduplicate(base, taken));
28	    }
