18	/**
19	 * Derives an owner's marketing segment, formatted {@code <TIER>_<AREA>}, from the owner's own
20	 * fields.
21	 *
22	 * <p>The {@code TIER} is {@link #PREMIUM} once the owner's effective membership level (see
23	 * {@link MembershipLevel#effective(Owner)}) reaches {@value #PREMIUM_MIN_LEVEL}, otherwise
24	 * {@link #STANDARD}. The {@code AREA} is {@link #METRO} when the owner's locality (see
25	 * {@link Locality}) is a known region, otherwise {@link #REGIONAL}.
26	 */
27	public final class OwnerSegment {
28	
29	    /** Tier for an owner whose effective membership level is at least {@link #PREMIUM_MIN_LEVEL}. */
30	    public static final String PREMIUM = "PREMIUM";
31	
32	    /** Tier for an owner below {@link #PREMIUM_MIN_LEVEL}. */
33	    public static final String STANDARD = "STANDARD";
34	
35	    /** Area for an owner whose locality resolves to a known region. */
36	    public static final String METRO = "METRO";
37	
38	    /** Area for an owner whose locality is {@link Locality#UNKNOWN}. */
39	    public static final String REGIONAL = "REGIONAL";
40	
41	    /** The lowest effective membership level that earns the {@link #PREMIUM} tier. */
42	    public static final int PREMIUM_MIN_LEVEL = 3;
43	
44	    private OwnerSegment() {
45	    }
46	
47	    /**
48	     * Derive the segment for the given owner.
49	     *
50	     * @param owner the owner (must not be {@code null}).
51	     * @return the segment, one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
52	     *         {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
53	     */
54	    public static String forOwner(Owner owner) {
55	        return tier(owner) + "_" + area(owner);
56	    }
57	
58	    private static String tier(Owner owner) {
59	        return MembershipLevel.effective(owner) >= PREMIUM_MIN_LEVEL ? PREMIUM : STANDARD;
60	    }
61	
62	    private static String area(Owner owner) {
63	        return Locality.UNKNOWN.equals(Locality.forPostcode(owner.getPostcode())) ? REGIONAL : METRO;
64	    }
65	}
