4	 * The Luhn (mod 10) algorithm. Computes the single check digit that, appended to a sequence
5	 * of digits, makes the whole sequence pass the Luhn checksum.
6	 */
7	public final class Luhn {
8	
9	    private Luhn() {
10	    }
11	
12	    /**
13	     * The Luhn check digit (0-9) over the digits contained in {@code value}; non-digit
14	     * characters are ignored.
15	     */
16	    public static int checkDigit(String value) {
17	        int sum = 0;
18	        boolean doubling = true;
19	        for (int i = value.length() - 1; i >= 0; i--) {
20	            char c = value.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (doubling) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
