1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The SHA-256 digest of a string as lower-case hexadecimal. Shared so every derivation that
9	 * needs a stable hash (household id, customer code) hashes identically.
10	 */
11	public final class Sha256 {
12	
13	    private Sha256() {
14	    }
15	
16	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
17	    public static String hex(String value) {
18	        try {
19	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
20	            StringBuilder hex = new StringBuilder(digest.length * 2);
21	            for (byte b : digest) {
22	                hex.append(String.format("%02x", b));
23	            }
24	            return hex.toString();
25	        }
26	        catch (NoSuchAlgorithmException ex) {
27	            throw new IllegalStateException("SHA-256 not available", ex);
28	        }
29	    }
30	}
