3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.stereotype.Component;
6	
7	/**
8	 * Monotonic sequence for {@link OwnerCreatedEvent}s. A single shared instance across all owner
9	 * creations so each emitted event carries a strictly increasing {@code seq}.
10	 */
11	@Component
12	public class OwnerCreatedEventSequence {
13	
14	    private final AtomicLong seq = new AtomicLong();
15	
16	    /**
17	     * The next sequence value.
18	     *
19	     * @return a value starting at 1 and increasing by one on each call.
20	     */
21	    public long next() {
22	        return this.seq.incrementAndGet();
23	    }
24	}
