3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.util.Sha256;
5	import org.springframework.samples.petclinic.util.Soundex;
6	
7	/**
8	 * Shared owner identity for the create-owner pipeline: derives the single canonical
9	 * {@code identityKey} that consolidates all duplicate detection.
10	 *
11	 * <p>The key is the lower-case hex SHA-256 (see {@link Sha256}) of
12	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with telephone
13	 * canonicalized to E.164 (see {@link OwnerTelephones}), email lower-cased (see
14	 * {@link OwnerEmails}) and the last name reduced to its Soundex code (see {@link Soundex}); a
15	 * missing telephone or email contributes an empty string. Two owners share this key only when
16	 * they submit the same telephone, email and phonetically-equal surname — {@link RequireUniqueIdentity}
17	 * uses it to reject an exact resubmission.
18	 */
19	public final class OwnerIdentities {
20	
21	    private OwnerIdentities() {
22	    }
23	
24	    /**
25	     * Canonical identity key for the given components: the SHA-256 hex of
26	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. {@code telephone}
27	     * is normalized to E.164 and {@code email} lower-cased before assembly; a {@code null}
28	     * telephone or email contributes an empty string.
29	     */
30	    public static String key(String telephone, String email, String lastName) {
31	        String canonical = part(OwnerTelephones.toE164(telephone)) + "|"
32	                + part(OwnerEmails.normalize(email)) + "|" + Soundex.encode(lastName);
33	        return Sha256.hex(canonical);
34	    }
35	
36	    /** Canonical {@link #key(String, String, String)} for an existing owner's stored fields. */
37	    public static String of(Owner owner) {
38	        return key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
39	    }
40	
41	    private static String part(String value) {
42	        return value == null ? "" : value;
43	    }
44	}
